const fit = (value, limit = 1024) => {
  const safe = String(value ?? '').replaceAll('@', '@\u200b').trim();
  if (!safe) return 'None.';
  return safe.length <= limit ? safe : safe.slice(0, limit - 2).trimEnd() + '…';
};
const soc = $json ?? {};
const actions = Array.isArray(soc.actions) ? soc.actions : [];
const fleet = soc.fleet ?? {};
const services = soc.services ?? {};
const maintenance = soc.maintenance ?? {};
const deployment = soc.deployment ?? {};
const security = soc.security ?? {};
const status = soc.summary?.status ?? 'warning';
const colors = { healthy: 0xa6e3a1, warning: 0xf9e2af, critical: 0xf38ba8 };
const queue = actions.length
  ? actions.map((item, index) => `${index + 1}. ${item.severity === 'critical' ? '⛔' : item.severity === 'warning' ? '⚠️' : '🔧'} ${item.message}`).join('\n')
  : '✅ Maintenance queue is empty. Spend the window on improvements instead of repairs.';
const disks = (fleet.disk_attention ?? []).length
  ? fleet.disk_attention.map((item) => `• ${item.host}: **${Number(item.used_percent).toFixed(1)}%** root used`).join('\n')
  : 'No host is above the 75% planning threshold.';
const staleBackups = (maintenance.stale_backups ?? []);
const backupText = [
  `${(maintenance.backups ?? []).length - staleBackups.length}/${(maintenance.backups ?? []).length} tracked backups are fresh`,
  ...(staleBackups.length ? staleBackups.map((item) => `⛔ ${item.host}/${item.timer}: ${item.age_hours == null ? 'never observed' : `${item.age_hours}h old`}`) : []),
  `Certificate actions: ${(services.internal_acme_attention ?? []).length + (services.external_tls_attention ?? []).length}`,
].join('\n');
const deploymentText = [
  `Live revision: **${String(deployment.majority_commit ?? 'unknown').slice(0, 8)}** on ${Number(deployment.targets ?? 0)} host(s)`,
  `Drifted: **${(deployment.drifted_hosts ?? []).length}** · Reboot pending: **${(deployment.reboot_pending ?? []).length}**`,
  `Deploy/build/fetch failures: **${(deployment.deployment_failures ?? []).length + (deployment.build_failures ?? []).length + (deployment.fetch_failures ?? []).length}**`,
].join('\n');
const securityText = [
  `Suricata: **${Number(security.suricata_alerts ?? 0)}** · pfSense high: **${Number(security.pfsense_high_alerts ?? 0)}**`,
  `SSH failures: **${Number(security.ssh_failures ?? 0)}** · OpenCanary: **${Number(security.opencanary_interactions ?? 0)}**`,
  `CrowdSec: **${Number(security.crowdsec_scenarios ?? 0)}** · Zeek notices: **${Number(security.zeek_notices ?? 0)}**`,
  'Use Grafana/TheHive for event detail; this card contains counts only.',
].join('\n');
const discordEmbed = {
  author: { name: 'GUILDEDTHORN // MAINTENANCE QUEUE' },
  title: fit(actions.length ? `${actions.length} item${actions.length === 1 ? '' : 's'} for this maintenance window` : 'Maintenance window is clear', 256),
  description: 'A deterministic weekly checklist from fleet, service, backup, certificate, deployment, and seven-day SOC telemetry.',
  color: colors[status] ?? colors.warning,
  fields: [
    { name: '📋 Ordered queue', value: fit(queue), inline: false },
    { name: '💾 Capacity', value: fit(disks), inline: false },
    { name: '🧰 Backups + certificates', value: fit(backupText), inline: false },
    { name: '🚀 Deployment debt', value: fit(deploymentText), inline: false },
    { name: '🛡️ Seven-day security pulse', value: fit(securityText), inline: false },
  ],
  footer: { text: 'Loom · planning only · no automatic remediation' },
  timestamp: new Date().toISOString(),
};
return { json: { discordEmbed, status, actionCount: actions.length } };
